import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Identify potential drivers based on t-statistics and effect sizes
    drivers = []
    seen_ids = set()

    # Sort features by t-statistic (absolute value) descending
    t_stats = []
    for fid in feats.ids:
        idx = feats.column(fid)
        try:
            t_stat = stats.ttest_ind(feats.x[feats.y==1, idx], 
                                   feats.x[feats.y==0, idx])[0]
            t_stats.append(abs(t_stat))
        except:
            t_stats.append(0)

    sorted_indices = np.argsort(t_stats)[::-1]

    # Select top features, avoiding near-duplicates
    for i in sorted_indices:
        if len(drivers) >= MAX_DRIVERS:
            break

        fid = feats.ids[i]
        # Check correlation with already selected drivers
        is_duplicate = False
        for d in drivers:
            if abs(np.corrcoef(feats.x[:, feats.column(fid)], 
                              feats.x[:, feats.column(d)])[0,1]) > 0.6:
                is_duplicate = True
                break

        if not is_duplicate:
            drivers.append(fid)
            seen_ids.add(fid)

    # If no strong drivers found, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build columns list with drivers and their correlates (avoiding duplicates)
    columns = list(drivers)
    for fid in feats.ids:
        if fid in seen_ids:
            continue
        # Add correlates of drivers but avoid near-duplicates
        for d in drivers:
            corr = abs(np.corrcoef(feats.x[:, feats.column(fid)], 
                                 feats.x[:, feats.column(d)])[0,1])
            if corr >= 0.6:
                columns.append(fid)
                seen_ids.add(fid)
                break

    # Create interaction terms between drivers
    products = []
    for i, a in enumerate(drivers):
        for b in drivers[i+1:]:
            # Only add if both features are in columns
            if a in columns and b in columns:
                products.append((a, b))

    # Simple weighted score using driver coefficients (simplified approach)
    loadings = {}
    for fid in columns:
        # Weight by t-statistic strength
        idx = feats.column(fid)
        try:
            t_stat = stats.ttest_ind(feats.x[feats.y==1, idx], 
                                   feats.x[feats.y==0, idx])[0]
            loadings[fid] = abs(t_stat)
        except:
            loadings[fid] = 0

    return Design(drivers=tuple(drivers), columns=tuple(columns), 
                  products=tuple(products), loadings=loadings)
